#!/usr/bin/env bash
set -uo pipefail
export KUBECONFIG=/root/.kube/config
mkdir -p /root/argocd-zh
echo "" | base64 -d > /root/argocd-zh/zh-cn.js
echo "" | base64 -d > /root/argocd-zh/nginx.conf
echo "" | base64 -d > /root/argocd-zh/deployment.yaml
ARGOCD_IP=$(kubectl -n argocd get svc argocd-server -o jsonpath='{.spec.clusterIP}')
sed -i "s/__ARGOCD_SVC_IP__/$ARGOCD_IP/g" /root/argocd-zh/nginx.conf
kubectl -n argocd create configmap argocd-zh-proxy \
  --from-file=nginx.conf=/root/argocd-zh/nginx.conf \
  --from-file=zh-cn.js=/root/argocd-zh/zh-cn.js \
  --dry-run=client -o yaml | kubectl apply -f -
kubectl apply -f /root/argocd-zh/deployment.yaml
kubectl -n argocd rollout restart deploy/argocd-zh-proxy >/dev/null
kubectl -n argocd rollout status deploy/argocd-zh-proxy --timeout=180s
kubectl -n argocd get pods | grep zh